<template><section class="shop-page"><header class="shop-heading"><div><span class="shop-eyebrow">DESTINOS DAS CONVERSAS</span><h1>Departamentos</h1><p>Organize a loja por setores e transfira conversas entre eles.</p></div><button class="shop-primary" @click="open()"><i class="ri-add-line"></i> Novo departamento</button></header><div v-if="notice" class="shop-alert" role="status">{{notice}}</div><div class="shop-department-grid"><article v-for="department in shop.departments" :key="department.id" class="shop-panel shop-department"><header><i class="ri-building-2-line"></i><span class="shop-status" :class="department.active?'AVAILABLE':'DISCONTINUED'">{{department.active?'Ativo':'Inativo'}}</span></header><h2>{{department.name}}</h2><p>{{department.description||'Setor da loja para encaminhamento de conversas.'}}</p><footer><RouterLink :to="{path:'/conversas',query:{departamento:department.id}}">Ver conversas <i class="ri-arrow-right-line"></i></RouterLink><button class="shop-secondary" @click="open(department)">Editar</button></footer></article></div><section v-if="!shop.departments.length" class="shop-panel shop-empty"><i class="ri-building-2-line"></i><h3>Para onde o cliente precisa ir?</h3><p>Cadastre Balcão, Açougue, Caixa ou os setores que fazem sentido no seu comércio.</p><button class="shop-primary" @click="open()">Cadastrar primeiro departamento</button></section><p class="shop-muted" style="margin-top:20px">Departamentos com conversas em andamento precisam ter essas conversas transferidas antes de serem desativados.</p><Teleport to="body"><div v-if="editing" class="shop-backdrop"><section class="shop-modal" role="dialog" aria-modal="true" aria-labelledby="department-title" @keydown.esc="!busy&&(editing=false)"><header><div><span class="shop-eyebrow">ORGANIZAÇÃO DA LOJA</span><h2 id="department-title">{{departmentId?'Editar departamento':'Novo departamento'}}</h2></div><button aria-label="Fechar" :disabled="busy" @click="editing=false"><i class="ri-close-line"></i></button></header><div v-if="error" class="shop-alert error" role="alert">{{error}}</div><form @submit.prevent="save"><fieldset :disabled="busy"><label>Nome do departamento<input v-model="form.name" required minlength="2" maxlength="80" placeholder="Ex.: Açougue"/></label><label>Descrição<textarea v-model="form.description" rows="3" maxlength="300" placeholder="Que tipo de solicitação este setor recebe?"/></label><label class="shop-checkbox"><input v-model="form.active" type="checkbox"/> Departamento ativo para receber conversas</label><div class="shop-modal-actions"><button type="button" class="shop-secondary" @click="editing=false">Cancelar</button><button class="shop-primary">{{busy?'Salvando…':'Salvar departamento'}}</button></div></fieldset></form></section></div></Teleport></section></template>
<script setup>
import { ref } from 'vue'
import { useShopStore } from '@/stores/shop.store'
import { shopApi } from '@/api/shop.api'
import { apiError } from '@/utils/shop'
const shop=useShopStore(),editing=ref(false),departmentId=ref(null),form=ref({}),error=ref(''),notice=ref(''),busy=ref(false)
function open(value=null){departmentId.value=value?.id||null;form.value={name:value?.name||'',description:value?.description||'',active:value?.active??true};error.value='';notice.value='';editing.value=true}
async function save(){busy.value=true;error.value='';try{await shopApi.saveDepartment(form.value,departmentId.value);editing.value=false;notice.value='Departamento salvo. A alteração foi registrada.';await shop.load()}catch(e){error.value=apiError(e)}finally{busy.value=false}}
</script>
